import numpy as npimport matplotlib.pyplot as pltfrom sklearn.gaussian_process import GaussianProcessRegressorfrom sklearn.gaussian_process.kernels import Matern # SAMPLE GPR IMPLEMENTATION USING A MATERN KERNEL FOR NOISE-FREE/NOISY DATA"""DATASET GENERATIONRemark: Can swap this out for data acquired from a table or deterministic black box. """X = np.linspace(start = 0, stop = 10, num = 1_000).reshape(-1,1)y = np.squeeze(X * np.sin(X))plt.figure()plt.plot(X, y, label = r"$f(x) = x \sin(x)$", linestyle="dotted")plt.legend()plt.xlabel("$x$")plt.ylabel("$f(x)$")plt.title("True generative process")"""NOISE-FREE TARGET GPR"""# select a few samplesrng = np.random.RandomState(1)training_indices = rng.choice(np.arange(y.size), size=6, replace=False)X_train, y_train = X[training_indices], y[training_indices]# fit a GP on these training data samples using a Matern kernel kernel = 1.0 * Matern(length_scale = 1.0, nu = 2.5) # nu = 2.5 typical for twice diff.# random opti restarts = 9 ==> thorough search of hyperparameter space # ensures algo isn't trapped in suboptimal local optima# MLEs computed as argmaxes of log-marginal-likelihoodgaussian_process = GaussianProcessRegressor(kernel=kernel, n_restarts_optimizer=9) gaussian_process.fit(X_train, y_train)# should observe Matern hyperparams (variance, length_scale) are optimized; nu fixedprint(gaussian_process.kernel_)# use kernel to compute mean prediction of full dataset and plot 95% CImean_prediction, std_prediction = gaussian_process.predict(X, return_std=True)plt.figure()plt.plot(X, y, label = r"$f(x) = x \sin(x)$", linestyle="dotted")plt.scatter(X_train, y_train, label="Observations")plt.plot(X, mean_prediction, label="Mean prediction")plt.fill_between(X.ravel(), mean_prediction - 1.96 * std_prediction,                  mean_prediction + 1.96 * std_prediction, alpha=0.5,                  label=r"95% confidence interval")plt.legend()plt.xlabel("$x$")plt.ylabel("$f(x)$")# plot should show that predictions made for data points close to those from # training set have narrower confidence intervalsplt.title("GPR with Matern Kernel on Noise-Free Dataset")"""NOISY TARGET GPR"""# add random Gaussian noise to target with arbitrary stdevnoise_std = 0.75y_train_noisy = y_train + rng.normal(loc=0.0, scale=noise_std, size=y_train.shape)# specify alpha parameter, interpretable as variance of Gaussian noisegaussian_process_noisy = GaussianProcessRegressor(kernel=kernel, alpha=noise_std**2, n_restarts_optimizer=9)gaussian_process_noisy.fit(X_train, y_train_noisy)mean_prediction_noisy, std_prediction_noisy = gaussian_process_noisy.predict(X, return_std=True)plt.figure()plt.plot(X, y, label = r"$f(x) = x \sin(x)$", linestyle="dotted")plt.errorbar(X_train, y_train_noisy, noise_std, linestyle="None",              color="tab:blue", marker=".", markersize=10, label="Observations"             )plt.plot(X, mean_prediction_noisy, label = "Mean prediction")plt.fill_between(X.ravel(), mean_prediction_noisy - 1.96 * std_prediction_noisy,         mean_prediction_noisy + 1.96 * std_prediction_noisy, color = "tab:orange",         alpha = 0.5, label = r"95% CI")plt.legend()plt.xlabel("$x$")plt.ylabel("$f(x)$")plt.title("GPR with Matern Kernel on Noisy Dataset")plt.show()